describe("services/invitation-service", () => {
  // can(actor, "member:invite", …) — a member cannot invite, an admin can.
  it("refuses an invite from an actor without member:invite", async () => {
    const tenant = await createTenant("invite-forbidden", "growth");

    await expect(
      invitationService.inviteMember(tenant.actors.member, {
        orgId: tenant.org.id,
        email: "newperson@invite-forbidden.test",
        role: "member",
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
  });

  // wouldExceedLimit(plan, "seats", seatsUsed) blocks the fourth seat on free.
  it("refuses an invite that would exceed the plan's seat quota", async () => {
    // The free plan tops out at 3 seats; createTenant already seeds 4 active
    // members (owner, admin, member, viewer), so the org starts over quota.
    const tenant = await createTenant("invite-seat-quota", "free");

    await expect(
      invitationService.inviteMember(tenant.actors.admin, {
        orgId: tenant.org.id,
        email: "onemore@invite-seat-quota.test",
        role: "member",
      }),
    ).rejects.toThrow(/seats/);
  });

  // A bulk invite checks the seat quota once, for the whole batch.
  it("checks the seat quota once for a bulk invite", async () => {
    const tenant = await createTenant("invite-bulk-quota", "starter");

    // Bring the org to 9 of its 10 starter seats: 4 from createTenant, 5 more
    // inserted directly so only a single seat remains.
    for (let i = 0; i < 5; i += 1) {
      const user = await userRepo.insertUser({
        email: `filler${i}@invite-bulk-quota.test`,
        name: `Filler ${i}`,
        passwordHash: "seed",
      });
      await memberRepo.insertMember(tenant.org.id, user.id, "member", null);
    }
    await expect(memberRepo.countActiveMembers(tenant.org.id)).resolves.toBe(9);

    // A batch of two exceeds the one remaining seat; the check runs once for
    // the whole batch, so nothing is created — not even the first invite.
    await expect(
      invitationService.inviteMembers(tenant.actors.admin, {
        orgId: tenant.org.id,
        invites: [
          { email: "batch-a@invite-bulk-quota.test", role: "member" },
          { email: "batch-b@invite-bulk-quota.test", role: "member" },
        ],
      }),
    ).rejects.toThrow(/seats/);

    await expect(
      invitationRepo.countPendingInvitations(tenant.org.id),
    ).resolves.toBe(0);

    // The same-sized single invite fits inside the one remaining seat.
    await expect(
      invitationService.inviteMembers(tenant.actors.admin, {
        orgId: tenant.org.id,
        invites: [{ email: "batch-c@invite-bulk-quota.test", role: "member" }],
      }),
    ).resolves.toHaveLength(1);
  });

  // consumeRateLimit(orgId, "member:invite") throttles invite bursts.
  it("rate-limits invites per organization", async () => {
    const tenant = await createTenant("invite-rate-limit", "growth");
    rateLimitState.allowed = false;

    await expect(
      invitationService.inviteMember(tenant.actors.admin, {
        orgId: tenant.org.id,
        email: "throttled@invite-rate-limit.test",
        role: "member",
      }),
    ).rejects.toThrow(/rate limit/);
  });

  // member.invited carries the email and the granted role.
  it("emits member.invited with the email and role", async () => {
    const tenant = await createTenant("invite-emit", "growth");

    let off: Unsubscribe | undefined;
    const received = await new Promise((resolve) => {
      off = subscribe("member.invited", (payload) => resolve(payload));
      void invitationService.inviteMember(tenant.actors.admin, {
        orgId: tenant.org.id,
        email: "invitee@invite-emit.test",
        role: "admin",
      });
    });
    off?.();

    expect(received).toMatchObject({
      orgId: tenant.org.id,
      email: "invitee@invite-emit.test",
      role: "admin",
    });
  });

  // Accepting creates the membership and emits member.joined.
  it("emits member.joined when an invitation is accepted", async () => {
    const tenant = await createTenant("invite-accept", "growth");
    const rawToken = "a".repeat(32);

    await invitationRepo.insertInvitation(
      tenant.org.id,
      {
        orgId: tenant.org.id,
        email: "acceptor@invite-accept.test",
        role: "member",
        expiresInDays: 14,
      },
      tenant.userIds.admin,
      hashToken(rawToken),
    );

    const newUser = await userRepo.insertUser({
      email: "acceptor@invite-accept.test",
      name: "Acceptor",
      passwordHash: "seed",
    });

    let off: Unsubscribe | undefined;
    const received = await new Promise((resolve) => {
      off = subscribe("member.joined", (payload) => resolve(payload));
      void invitationService.acceptInvitation(newUser.id, { token: rawToken });
    });
    off?.();

    expect(received).toMatchObject({
      orgId: tenant.org.id,
      userId: newUser.id,
      role: "member",
    });

    await expect(
      memberRepo.findMember(tenant.org.id, newUser.id),
    ).resolves.not.toBeNull();
  });

  // An expired or revoked token is refused rather than silently accepted.
  it("refuses an expired or revoked invitation token", async () => {
    const tenant = await createTenant("invite-revoked", "growth");
    const revokedToken = "b".repeat(32);

    const invitation = await invitationRepo.insertInvitation(
      tenant.org.id,
      {
        orgId: tenant.org.id,
        email: "revoked@invite-revoked.test",
        role: "member",
        expiresInDays: 14,
      },
      tenant.userIds.admin,
      hashToken(revokedToken),
    );
    await invitationRepo.revokeInvitation(tenant.org.id, invitation.id);

    const newUser = await userRepo.insertUser({
      email: "revoked@invite-revoked.test",
      name: "Revoked",
      passwordHash: "seed",
    });

    await expect(
      invitationService.acceptInvitation(newUser.id, { token: revokedToken }),
    ).rejects.toThrow(/revoked/);

    const expiredToken = "c".repeat(32);
    await invitationRepo.insertInvitation(
      tenant.org.id,
      {
        orgId: tenant.org.id,
        email: "expired@invite-revoked.test",
        role: "member",
        expiresInDays: -1,
      },
      tenant.userIds.admin,
      hashToken(expiredToken),
    );

    const secondUser = await userRepo.insertUser({
      email: "expired@invite-revoked.test",
      name: "Expired",
      passwordHash: "seed",
    });

    await expect(
      invitationService.acceptInvitation(secondUser.id, { token: expiredToken }),
    ).rejects.toThrow(/expired/);
  });
});
/**
 * The background job layer: the in-process queue, the scheduler's cadence and
 * the two jobs whose behaviour other layers depend on — the overdue scan that
 * feeds the notification fan-out, and the trial expiry that moves plans.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("./_support/doubles/misc")).loggerModule);

import { subscribe } from "@/lib/event-bus";
import {
  drain,
  enqueue,
  isSchedulerRunning,
  pendingCount,
  resetQueue,
  startScheduler,
  stopScheduler,
} from "@/server/jobs";
import { backoffMs } from "@/server/jobs/webhook-delivery-job";
import { shouldRunForOrg } from "@/server/jobs/digest-email-job";
import { runOverdueIssueJob } from "@/server/jobs/overdue-issue-job";
import { runUsageRollupJob } from "@/server/jobs/usage-rollup-job";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as issueService from "@/server/services/issue-service";
import { toIsoTimestamp } from "@/types/common";
import { createTenant, issueInput, useTemporaryDatabase } from "./_support/fixtures";
import type { Tenant } from "./_support/fixtures";
import type { Unsubscribe } from "@/types/event";

let cleanup: () => void;
let tenant: Tenant;
const detachers: Unsubscribe[] = [];

const PAST = "2026-01-01T00:00:00.000Z";
const NOW = new Date("2026-06-01T07:00:00.000Z");

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("jobs");
  await usageRepo.recomputeUsage(tenant.org.id);
});

afterEach(() => {
  while (detachers.length > 0) detachers.pop()?.();
  resetQueue();
  stopScheduler();
});

afterAll(() => {
  cleanup();
});

describe("the in-process queue", () => {
  it("is idempotent on the job id", () => {
    const job = {
      id: "usage-rollup:1",
      kind: "usage-rollup" as const,
      runAt: toIsoTimestamp(NOW),
      attempts: 0,
      payload: {},
    };

    enqueue(job);
    enqueue(job);

    expect(pendingCount()).toBe(1);
  });

  it("leaves jobs scheduled in the future alone", async () => {
    enqueue({
      id: "usage-rollup:future",
      kind: "usage-rollup",
      runAt: toIsoTimestamp(new Date(Date.now() + 3_600_000)),
      attempts: 0,
      payload: {},
    });

    await expect(drain()).resolves.toBe(0);
    expect(pendingCount()).toBe(1);
  });

  it("runs a due job and removes it", async () => {
    enqueue({
      id: "usage-rollup:due",
      kind: "usage-rollup",
      runAt: toIsoTimestamp(new Date(Date.now() - 1_000)),
      attempts: 0,
      payload: {},
    });

    await expect(drain()).resolves.toBe(1);
    expect(pendingCount()).toBe(0);
  });
});

describe("the scheduler", () => {
  it("reports whether it is running and stops cleanly", () => {
    expect(isSchedulerRunning()).toBe(false);
    startScheduler();
    expect(isSchedulerRunning()).toBe(true);
    stopScheduler();
    expect(isSchedulerRunning()).toBe(false);
  });
});

describe("the overdue scan", () => {
  it("emits issue.overdue for a past-due open issue, once", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Late already",
        assigneeId: tenant.userIds.member,
        dueAt: PAST,
      }),
    );

    const seen: string[] = [];
    detachers.push(
      subscribe("issue.overdue", (payload) => {
        seen.push(payload.issueId);
      }),
    );

    const result = await runOverdueIssueJob(NOW);

    expect(seen).toEqual([issue.id]);
    expect(result.kind).toBe("overdue-issues");
    expect(result.processed).toBe(1);
    expect(result.failed).toBe(0);
  });

  it("ignores an overdue issue once it is archived", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Late but archived",
        dueAt: PAST,
      }),
    );
    await issueService.archiveIssue(
      tenant.actors.member,
      tenant.org.id,
      issue.id,
    );

    const overdue = await issueRepo.listOverdueIssues(
      tenant.org.id,
      toIsoTimestamp(NOW),
    );

    expect(overdue.map((row) => row.id)).not.toContain(issue.id);
  });

  it("ignores an overdue issue once it is closed", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Late but done",
        dueAt: PAST,
      }),
    );
    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      status: "done",
    });

    const overdue = await issueRepo.listOverdueIssues(
      tenant.org.id,
      toIsoTimestamp(NOW),
    );

    expect(overdue.map((row) => row.id)).not.toContain(issue.id);
  });
});

describe("the usage rollup", () => {
  it("recounts the tenant's live rows", async () => {
    const result = await runUsageRollupJob(NOW);
    expect(result.processed).toBeGreaterThan(0);

    const usage = await usageRepo.getUsage(tenant.org.id);
    const live = await issueRepo.listIssues({
      orgId: tenant.org.id,
      limit: 100,
      cursor: null,
    });

    expect(usage.issuesUsed).toBe(live.total);
    expect(usage.seatsUsed).toBe(4);
  });
});

describe("pure job helpers", () => {
  it("backs delivery attempts off exponentially, with a ceiling", () => {
    expect(backoffMs(0)).toBe(0);
    expect(backoffMs(1)).toBe(1_000);
    expect(backoffMs(2)).toBe(2_000);
    expect(backoffMs(3)).toBe(4_000);
    expect(backoffMs(30)).toBe(300_000);
  });

  it("runs the digest only during the org's configured UTC hour", () => {
    const org = {
      ...tenant.org,
      settings: { ...tenant.org.settings, digestHourUtc: 7 },
    };

    expect(shouldRunForOrg(org, NOW)).toBe(true);
    expect(
      shouldRunForOrg(org, new Date("2026-06-01T08:00:00.000Z")),
    ).toBe(false);
    expect(
      shouldRunForOrg({ ...org, archivedAt: toIsoTimestamp(NOW) }, NOW),
    ).toBe(false);
  });
});

